import { Component } from '@angular/core';
import { Button, HeaderButton, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { CreditoService } from '../../../controllers/credito.service';
import { CREDITOS_ADVANCED_SEARCH } from '../../creditos/creditos.busqueda.avanzada';
import { EstadoCuenta } from '../../../models/estado.cuenta';
import { Router } from '@angular/router';
import { Credito } from '../../../models/credito.model';
import { CREDITOS_FILTERS } from '../../creditos/creditos.simple.filters';
import { FormsModule } from '@angular/forms';
import { CreditoEventoCobro } from '../../../models/credito.evento.cobro';
import { Convenio } from '../../../models/convenio';
import { UtilsService } from '../../../services/utils.service';

const TABLA_DEF: TableDefinition = {
  emptyMsg: 'No hay creditos con estados de cuenta activos.',
  columns: [
    {
      key: 'id',
      header: 'ID',
    },
    {
      key: 'row',
      header: 'Nombre Cliente',
      function: (param: Credito, utils: UtilsService) => {
        return utils.nombreClienteFromCredito(param)
      }
    },
    {
      key: 'estados_cuenta',
      header: 'Estado',
      function: (estado: EstadoCuenta) => {
        return (estado.pagos_requeridos - estado.pagos_realizados) >= 3 ? 'VENCIDO' : 'CARTERA'
      },
    },
    {
      key: 'convenios',
      header: 'Total convenios',
      function: (convenios: Convenio[]) => {
        return convenios.length.toString()
      }
    },
    {
      key: 'convenios',
      header: 'Convenios Activos',
      function: (convenios: Convenio[]) => {
        return convenios.filter((convenio) => convenio.estatus === 'ACTIVO').length.toString()
      }
    },
    {
      key: 'estados_cuenta',
      header: 'Saldo Vencido',
      subKey: 'saldo_vencido',
      pipe: 'currency'
    },
    {
      key: 'estados_cuenta',
      header: 'Vencido desde',
      subKey: 'vencido_desde',
      pipe: 'date'
    },
    {
      key: 'estados_cuenta',
      header: 'Pagos Vencidos',
      function: (estado: EstadoCuenta) => {
        return (estado.pagos_requeridos - estado.pagos_realizados).toString()
      },
    },
    {
      key: 'productos_financieros',
      subKey: 'alias',
      header: 'P Financiero'
    },
    {
      key: 'sucursales',
      subKey: 'nombre',
      header: 'Sucursal'
    },
  ]
}
const EDITAR_BUTTON: Button = {
  title: 'Ver convenios',
  style: {
    button: 'btn btn-sm btn-primary',
    icon: 'bi bi-list'
  },
}

const ASIGNAR_JURIDICO: RowButton = {
  key: 'convenio',
  title: 'Nuevo Convenio',
  style: {
    button: 'btn btn-sm btn-success',
    icon: 'bi bi-journal-plus'
  }
}

const DETALLES_BUTTON: RowButton = {
  key: 'detalles',
  title: 'Ver Detalles',
  style: {
    button: 'btn btn-sm btn-info',
    icon: 'bi bi-eye-fill'
  }
}
@Component({
    selector: 'app-creditos-atrasados',
    imports: [
        TablaComponent,
        FormsModule,
    ],
    templateUrl: './creditos-atrasados.component.html',
    styleUrl: './creditos-atrasados.component.css'
})
export class CreditosAtrasadosConveniosComponent {
  tabla = TABLA_DEF
  edit = EDITAR_BUTTON
  advancedSearch = CREDITOS_ADVANCED_SEARCH
  simpleFilters = CREDITOS_FILTERS
  asignarJuridico = ASIGNAR_JURIDICO
  detalles= DETALLES_BUTTON
  filtros: {
    filtro: string;
    meses_vencidos: number | null;
    incluir_juridico: number | null;
    monto_atrasado: number | null;
    adeudo_total: number | null;
  } = {
      filtro: 'estado',
      meses_vencidos: null,
      incluir_juridico: null,
      monto_atrasado: null,
      adeudo_total: null
    }
  showNew: boolean = false
  creditoEdit?: Credito

  constructor(
    public creditoController: CreditoService,
    private router: Router,
  ) { }

  onRowButtonClick(event: RowButtonClickEvent<Credito>) {
    this.creditoEdit = event.row
    switch(event.key){
      case 'convenio':
        this.router.navigate(['/main/convenios/nuevo/' + this.creditoEdit.id])
        break
      case 'detalles':
        this.router.navigate(['/main/convenios/detalles/' + this.creditoEdit.id])
        break;
    }
  }

  limpiarFiltros() {
    this.filtros.meses_vencidos = null
    this.filtros.incluir_juridico = null
    this.filtros.monto_atrasado = null
    this.filtros.adeudo_total = null
  }
}
