import { Component, Input, SimpleChanges } from '@angular/core';
import { RouterLink } from '@angular/router';
import { Convenio } from '../../../../models/convenio';
import { TablaAmortizacionService } from '../../../../services/documentosLegales/contratos/tabla_amortizacion.service';
import { PagareService } from '../../../../services/documentosLegales/contratos/pagare.service';
import { convenioPagoPF } from '../../../../services/documentosLegales/contratos/convenio_pago_pf.service';
import { convenioPagoPM } from '../../../../services/documentosLegales/contratos/convenio_pago_pm.service';
import { convenioReestructuraPF } from '../../../../services/documentosLegales/contratos/convenio_reestructura_pf.service';
import { convenioReestructuraPM } from '../../../../services/documentosLegales/contratos/convenio_reestructura_pm.service';
import { ConvenioJudicialPF } from '../../../../services/documentosLegales/contratos/convenio_judicial_pf.service';
import { ConvenioJudicialPM } from '../../../../services/documentosLegales/contratos/convenio_judicial_pm.service';
import { ConvenioExtrajudicialPF } from '../../../../services/documentosLegales/contratos/convenio_extrajudicial_pf.service';
import { ConvenioExtrajudicialPM } from '../../../../services/documentosLegales/contratos/convenio_extrajudicial_pm.service';
import { Credito } from '../../../../models/credito.model';
import { ConvenioService } from '../../../../controllers/convenio.service';
import { CreditoService } from '../../../../controllers/credito.service';
import { PagosResponse } from '../../../cotizador/cotizador.component';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';

@Component({
  selector: 'app-convenio-header',
  imports: [
    RouterLink,
  ],
  templateUrl: './convenio-header.component.html',
  styleUrl: './convenio-header.component.css'
})
export class ConvenioHeaderComponent {
  @Input() convenio?: Convenio
  @Input() credito?: Credito
  @Input() amortizaciones?: PagosResponse

  fechaPagare = ''

  constructor(
    public tabla_amortizacion: TablaAmortizacionService,
    public pagare: PagareService,
    public convenioPagoPF: convenioPagoPF,
    public convenioPagoPM: convenioPagoPM,
    public convenioReestructuraPF: convenioReestructuraPF,
    public convenioRestructuraPM: convenioReestructuraPM,
    public convenioJudicialPF: ConvenioJudicialPF,
    public convenioJudicialPM: ConvenioJudicialPM,
    public convenioExtraPf: ConvenioExtrajudicialPF,
    public convenioExtraPm: ConvenioExtrajudicialPM,
    private convenioController: ConvenioService,
    private creditoController: CreditoService,
    private dialog: VanillaDialogService,
  ) { }

  ngOnChanges(changes:SimpleChanges){
    if(changes['convenio'] && this.convenio){
      this.setFechaPagare()
    }
  }

  private setFechaPagare(){
    if(!this.convenio?.fecha_convenio) return;
    const date= new Date(this.convenio.fecha_convenio.substring(0,10) + 'T17:00:00Z')
    this.fechaPagare = new Date(date.getFullYear(), date.getMonth() +4, 0).toISOString().substring(0,10)
  }

  public async terminar(estado: 'CANCELADO' | 'CONCLUIDO'|'ACTIVO') {
    const convenios= await this.convenioController.all({ conditionals:{credito_id:this.credito?.id, deleted_at:null}, columns:['id','estatus']})
    if(estado=='ACTIVO' && convenios.some(c => c.estatus=='ACTIVO')){
      this.dialog.show({
        title:'Esto no se puede hacer.',
        body:'Este crédito ya cuenta con un convenio activo, no puede activar uno mas, solo puede tener uno activo a la vez',
        tipo:'danger',
      })
      return;
    }
    await this.convenioController.concluir(this.convenio, estado)
    this.creditoController.actualizarEstadoCuenta(this.credito)
  }

}
