import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { Convenio } from '../models/convenio';
import { firstValueFrom } from 'rxjs';
import { VanillaDialogService } from '../services/vanilla-dialog/vanilla-dialog.service';

@Injectable({
  providedIn: 'any'
})
export class ConvenioService extends SuperService<Convenio> {
  protected override model: string = "convenios";
  protected override columns: (keyof Convenio)[] = [
    'juridico_id',
    'credito_id',
    "tipo_convenio",
    'estatus',
    'plazo',
    'fecha_inicio',
    'fecha_conclusion',
    "capital",
    "interes_ordinario",
    "interes_moratorio_condonado",
    "interes_moratorio_cobrado",
    "gastos_judiciales",
    'usuario_id',
    'pagare_url',
    'iva_interes_ordinario',
    "monto_abono_inicial",
    "fecha_convenio",
  ]

  constructor(
    injector: Injector,
    private dialog: VanillaDialogService,
  ) {
    super(injector)
  }

  public async concluir(convenio: Convenio | undefined, estado: 'CONCLUIDO' | 'CANCELADO' | 'ACTIVO') {
    if (!convenio) return;
    let today: string | null = new Date().toISOString().substring(0, 10)
    if (convenio.estatus == 'ACTIVO') today = null;
    this.fastUpdate(convenio, { estatus: estado, fecha_conclusion: today })
  }
}