import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { CreditoService } from '../../../controllers/credito.service';
import { ActivatedRoute } from '@angular/router';
import { DataViewSectionComponent } from "../../../shared/data-view-section/data-view.component";


@Component({
    selector: 'app-detalles-credito-convenios',
    imports: [
    DataViewSectionComponent
],
    templateUrl: './detalles-credito-convenios.component.html',
    styleUrl: './detalles-credito-convenios.component.css'
})
export class DetallesCreditoConveniosComponent {
  credito?:Credito

  sectionShows:any={}

  sections=[
    'Clientes',
    'Cli. Teléfonos',
    'Negocio',

  ]

  constructor(
    private creditoController: CreditoService,
    private route :ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params)=>{
      const id = params['credito_id']
      if(id){
        this.credito= await this.creditoController.find(id,['*'])
      }
    })
  }
}
