@Component({
  selector: 'app-form-datos-morales',
  imports: [
    GenericFormComponent,
    BuscadorDatosPersonalesComponent
  ],
  templateUrl: './form-datos-morales.component.html',
  styleUrl: './form-datos-morales.component.css'
})
export class FormDatosMoralesComponent implements OnInit {
  @ViewChild('genericFormRl') form!:GenericFormComponent<DatoPersonal>
  @Input() datoPersonaMoral?: DatoPersonaMoral;

  representanteLegal?: DatoPersonal;
  formPM: Form = FORM_PM;
  formRL: Form = FORM_RL;

  constructor(
    public controller: DatoPersonaMoralService,
    public datoPersonalController: DatoPersonalService,
  ) {
  }

  ngOnInit(): void {
    this.getDatos();
  }

  async getDatos() {
    if (this.datoPersonaMoral) {
      const datos = await this.controller.find(this.datoPersonaMoral.id, [
        "ciudades",
        "representanteLegal",
        "representanteLegal.ciudades",
        "representanteLegal.telefonosPersonales",
      ]);

      this.datoPersonaMoral = { ...this.datoPersonaMoral, ...datos };
      this.representanteLegal = this.datoPersonaMoral.representante_legal;
    }
  }

  updateDatosPersonaMoral(dp: DatoPersonal) {
    this.datoPersonaMoral!.representante_legal_id = dp.id
    this.controller.update(this.datoPersonaMoral!.id, { representante_legal_id: dp.id })
  }

  limpiar(){
    this.representanteLegal=undefined
    this.datoPersonaMoral!.representante_legal=undefined
    this.controller.update(this.datoPersonaMoral!.id, { representante_legal_id: null })
    this.form.cleanForm()
  }
}
