import { Component } from '@angular/core';
import { TablaComponent, TableDefinition } from "../../../shared/tabla/tabla.component";
import { ConvenioService } from '../../../controllers/convenio.service';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute, Router } from '@angular/router';
import { Convenio } from '../../../models/convenio';
import { BuscadorCreditosComponent } from "../../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";


const TABLA_DEF:TableDefinition={
  columns:[
    'id',
    'credito_id',
    {
      key:'row',
      header:'Nombre Cliente',
      function:(param:Convenio, utils:UtilsService)=>{
        return utils.nombreClienteFromCredito(param.credito)
      }
    },
    'estatus',
    {
      key:'fecha_inicio',
      header:'Fecha Inicio',
      pipe:'date'
    },
    {
      key:'fecha_conclusion',
      header:'Fecha Conclusión',
      pipe:'date'
    },
    'deleted_at'
  ]
}

@Component({
    selector: 'app-list-convenios',
    imports: [
    TablaComponent,
    BuscadorCreditosComponent
],
    templateUrl: './list-convenios.component.html',
    styleUrl: './list-convenios.component.css'
})
export class ListConveniosComponent {
  credito_id?:number
  tabla=TABLA_DEF
  extraData={}

  constructor(
    public conveniosController: ConvenioService,
    private utils: UtilsService,
    private route: ActivatedRoute,
    private router:Router,
  ){}

  ngOnInit(){
    this.route.params.subscribe((params)=>{
      this.credito_id= params['credito_id']
      if(this.credito_id){
        this.extraData={
          conditionals: JSON.stringify([
            ['credito_id','=', this.credito_id]
          ])
        }
      }
    })
  }

  updateUrl(id:number){
    this.router.navigate(['/main/convenios/list',id])
  }
}
